structure.mermaidSource:
flowchart TD
  start_crit["Início: Identificar o verbo sob auditoria"] --> dec_verbo_crit{"Qual verbo está em análise?"}
  dec_verbo_crit -- "Implicar" --> dec_sent_implicar{"Sentido é 'acarretar / ter como consequência'?"}
  dec_sent_implicar -- "Sim" --> dec_prep_em{"Há presença da preposição 'em' no complemento?"}
  dec_prep_em -- "Sim (com 'em')" --> res_implicar_elimina["ELIMINE imediatamente a preposição 'em': verbo é VTD ('Isto implica demissão')"]
  dec_prep_em -- "Não (sem preposição)" --> res_implicar_correto["Construção correta: VTD com objeto direto sem preposição"]
  dec_sent_implicar -- "Não (outro sentido)" --> res_implicar_outros["Outros sentidos: 'implicar com' (birra) ou 'implicar-se em' (envolver-se)"]
  dec_verbo_crit -- "Preferir" --> dec_tem_intens{"Há termo de intensidade ('mais', 'antes', 'mil vezes')?"}
  dec_tem_intens -- "Sim" --> proc_elimina_intens["ELIMINE o termo intensificador ('mais', 'antes', 'mil vezes')"]
  dec_tem_intens -- "Não" --> dec_conector_pref{"Qual elemento introduz o segundo termo?"}
  proc_elimina_intens --> dec_conector_pref
  dec_conector_pref -- "'do que' ou 'que nem'" --> res_pref_elimina_doque["ELIMINE 'do que' / 'que nem' e conecte unicamente pela preposição 'A'"]
  dec_conector_pref -- "Preposição 'A'" --> res_pref_correto["Construção canônica correta: 'Prefiro café a chá'"]
  dec_conector_pref -- "Outro elemento" --> res_pref_invalido["Construção inválida: PREFERIR exige estritamente a preposição simples 'A'"]
